import React, { useState } from 'react';
import { Box, Button, Chip, Paper, Typography } from '@mui/material';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { sampleNavitars } from '../data/sampleNavitars';
import type { NavitarDesignProps } from './NavitarDesign';
import { NavitarArtImg } from './NavitarArtImg';
import AttackEditor from './AttackEditor';
import { defaultAttacksFor, isValidAttacks, type NavitarAttack } from '../utils/attacks';
import { elementColor, elementEmoji } from '../utils/navitarArt';
import { isLockedNavitar } from '../utils/lockedRoster';
import { isOwnerModeActive } from '../utils/ownerMode';

// First-navitar adoption (Round 32.6, Eddie 2026-11-18 ~17:00 PT):
// adopting lives ONLY in the Navidex — "that should only live on
// the Navidex page, in case the stage is not loading." The Home
// Step-2 funnel (the oval adoption grid + collection picker) is
// gone; this section is the one front door for a player who owns
// no navitar yet, rendered at the top of the Navidex grids.
//
// Adoption is DELIBERATE, exactly as it was on Home: browsing the
// roster adopts nothing, tapping a locked/unowned card adopts
// nothing (Round 16's rule stands) — the player picks a starter,
// reviews its five starting moves, and presses the explicit
// "Adopt <name>" confirm. The adopted fighter lands as the
// player's active navitar (createUserNavitar's own rule), fresh
// at Level 1. Once the player owns any navitar this section
// renders nothing: choosing among owned fighters is the grids'
// gold-dot job, unchanged.
//
// The starter move defaults moved here from Home with the funnel
// (same record, same values).
const ROSTER_SKILLS: Record<string, string[]> = {
  Frostbite: ['Ice Blast', 'Frost Shield'],
  Emberwing: ['Ember Strike', 'Flame Wing'],
  Leafblade: ['Leaf Slash', 'Thorn Guard'],
  Shadowmaw: ['Shadow Bite', 'Dark Veil'],
  Luminara: ['Light Beam', 'Radiant Shield'],
  Quantix: ['Quantum Leap', 'Phase Shift'],
  Voltwing: ['Thunder Dive', 'Static Shock'],
  Spiritmaw: ['Soul Roar', 'Spirit Guard'],
  Tidefang: ['Tidal Wave', 'Aqua Fang'],
};

const AdoptNavitar: React.FC = () => {
  const { navitars, createUserNavitar } = useNavitarFightClub();
  // The fighter the player is reviewing for adoption (the panel
  // below the grid) — selecting opens the review, it does NOT
  // adopt; only the panel's explicit Adopt button does.
  const [adoptTarget, setAdoptTarget] = useState<NavitarDesignProps | null>(null);
  const [adoptAttacks, setAdoptAttacks] = useState<NavitarAttack[]>([]);
  const [adoptError, setAdoptError] = useState('');

  if (navitars.length > 0) return null;

  const handleSelectAdopt = (roster: NavitarDesignProps) => {
    // Locked designs are never adoptable (Eddie, 2026-11-13);
    // the starter roster is playable by design, so this is the
    // enforcement seam if a locked name ever reached the list.
    if (isLockedNavitar(roster.name) && !isOwnerModeActive()) return;
    const skills = ROSTER_SKILLS[roster.name] ?? ['Quick Attack'];
    setAdoptTarget(roster);
    setAdoptAttacks(defaultAttacksFor(roster.type, skills));
    setAdoptError('');
  };

  const handleAdopt = () => {
    if (!adoptTarget) return;
    if (!isValidAttacks(adoptAttacks)) {
      setAdoptError('Give each attack a unique name (up to 40 characters).');
      return;
    }
    const roster = adoptTarget;
    const skills = ROSTER_SKILLS[roster.name] ?? ['Quick Attack'];
    createUserNavitar(roster.name, skills, roster.imageUrl, roster.type, adoptAttacks);
    setAdoptTarget(null);
    setAdoptError('');
  };

  return (
    <Paper data-testid="navidex-adopt" sx={{ p: 3, mb: 3 }}>
      <Typography variant="h6" sx={{ fontWeight: 700 }}>
        Adopt your first navitar
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        This is where every fighter is met and chosen — the Navidex is the one home for adopting and
        choosing, so your collection works even when a 3D model can't load. Pick a starter, review
        its five starting moves, and press Adopt. Adopting always starts fresh at Level 1 — from
        there it is yours: feed it, train it, stroll with it, and it grows with you.
      </Typography>
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: 'repeat(auto-fill, minmax(140px, 1fr))',
            sm: 'repeat(auto-fill, minmax(170px, 1fr))',
          },
          gap: 2,
        }}
      >
        {sampleNavitars.map(roster => {
          const selected = adoptTarget?.name === roster.name;
          return (
            <Box
              key={roster.name}
              data-testid={`adopt-card-${roster.name}`}
              sx={{
                textAlign: 'center',
                p: 1.5,
                borderRadius: 2,
                border: '1px solid',
                borderColor: selected ? elementColor(roster.type) : 'divider',
                bgcolor: 'background.default',
              }}
            >
              <Box
                sx={{
                  width: 96,
                  height: 96,
                  borderRadius: '50%',
                  overflow: 'hidden',
                  mx: 'auto',
                  mb: 1,
                  bgcolor: elementColor(roster.type),
                }}
              >
                {roster.imageUrl ? (
                  <NavitarArtImg
                    src={roster.imageUrl}
                    alt={roster.name}
                    element={roster.type}
                    style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                  />
                ) : (
                  <Box
                    sx={{
                      width: '100%',
                      height: '100%',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: '2.4rem',
                    }}
                  >
                    {elementEmoji(roster.type)}
                  </Box>
                )}
              </Box>
              <Typography sx={{ fontWeight: 700 }}>{roster.name}</Typography>
              <Chip
                size="small"
                label={`${elementEmoji(roster.type)} ${roster.type} · you start at Lv 1`}
                sx={{ my: 1 }}
              />
              <Button
                variant={selected ? 'contained' : 'outlined'}
                fullWidth
                data-testid={`adopt-start-${roster.name}`}
                aria-label={`Adopt ${roster.name}`}
                onClick={() => handleSelectAdopt(roster)}
              >
                Adopt
              </Button>
            </Box>
          );
        })}
      </Box>
      {adoptTarget && (
        <Box
          data-testid="navidex-adopt-panel"
          sx={{
            mt: 3,
            p: 2,
            border: '1px solid',
            borderColor: 'divider',
            borderRadius: 2,
          }}
        >
          <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 700 }}>
            Adopt {adoptTarget.name} — attacks
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            Fresh Lv 1 {adoptTarget.type} — tweak the five moves below, or adopt as-is.
          </Typography>
          <AttackEditor
            attacks={adoptAttacks}
            element={adoptTarget.type}
            level={1}
            onChange={next => {
              setAdoptAttacks(next);
              if (adoptError) setAdoptError('');
            }}
          />
          {adoptError && (
            <Typography variant="body2" color="error" sx={{ mt: 1 }}>
              {adoptError}
            </Typography>
          )}
          <Box sx={{ display: 'flex', gap: 1, mt: 2, flexWrap: 'wrap' }}>
            <Button variant="contained" data-testid="adopt-confirm" onClick={handleAdopt}>
              Adopt {adoptTarget.name}
            </Button>
            <Button
              onClick={() => {
                setAdoptTarget(null);
                setAdoptError('');
              }}
            >
              Cancel
            </Button>
          </Box>
        </Box>
      )}
    </Paper>
  );
};

export default AdoptNavitar;
