import React, { useState } from 'react';
import { Box, Button, Paper, TextField, Typography } from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import {
  checkAdminPassword,
  clearAdminPassword,
  hasAdminPassword,
  setAdminPassword,
  unlockPortal,
  lockPortal,
  usePortalUnlocked,
} from '../utils/adminPortal';

// ADMINISTRATOR PORTAL DOOR (Round 37-V2, Eddie 2026-11-20): the
// LAST section on the Profile page — no settings to open, nothing
// to hunt for. Eddie's words: "add an administrator portal at the
// bottom of the page and I could just go in there and just give
// me a special password."
//
// First open on a device: Eddie sets the password himself (only
// its SHA-256 hash is kept, on this device — see adminPortal.ts).
// Later opens ask for it. A right answer unlocks the portal for
// the browser session and walks straight into the venue window
// (/admin-venues). The Owner Mode door in the Owner Mode section
// above still exists — this is a second, findable entrance, and
// the data behind both doors stays locked to Eddie's owner
// sign-in (Supabase RLS), exactly as it was.
const AdminPortalDoor: React.FC = () => {
  const navigate = useNavigate();
  const unlocked = usePortalUnlocked();
  const [hashExists, setHashExists] = useState<boolean>(hasAdminPassword);
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [message, setMessage] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const enter = async () => {
    setBusy(true);
    setMessage(null);
    const okPw = await checkAdminPassword(password);
    setBusy(false);
    if (!okPw) {
      setMessage("That's not it — try again.");
      return;
    }
    setPassword('');
    unlockPortal();
    navigate('/admin-venues');
  };

  const setAndEnter = async () => {
    if (password.length < 4) {
      setMessage('Make it at least 4 characters.');
      return;
    }
    if (password !== confirm) {
      setMessage("Those don't match — try again.");
      return;
    }
    setBusy(true);
    await setAdminPassword(password);
    setBusy(false);
    setHashExists(true);
    setPassword('');
    setConfirm('');
    setMessage(null);
    unlockPortal();
    navigate('/admin-venues');
  };

  const reset = () => {
    clearAdminPassword();
    setHashExists(false);
    setPassword('');
    setConfirm('');
    setMessage('Password cleared on this device — set a new one below.');
  };

  return (
    <Paper sx={{ p: 3, mb: 3 }} data-testid="admin-portal-door">
      <Typography variant="h6" gutterBottom>
        🏛️ Administrator portal
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        Venue operations: applications waiting on you, approvals, and the saved venue profiles —
        region by region.
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        This password guards the door on this device — the venue records themselves stay locked to
        your owner sign-in.
      </Typography>

      {unlocked ? (
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
          <Button variant="contained" component={RouterLink} to="/admin-venues">
            Enter venue operations →
          </Button>
          <Button variant="text" size="small" onClick={() => lockPortal()}>
            Lock
          </Button>
          <Typography variant="body2" color="text.secondary">
            Unlocked on this device for this visit.
          </Typography>
        </Box>
      ) : hashExists ? (
        <Box>
          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'flex-start' }}>
            <TextField
              size="small"
              type="password"
              label="Administrator password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter' && password) void enter();
              }}
              inputProps={{ 'data-testid': 'admin-portal-password' }}
            />
            <Button variant="contained" disabled={busy || !password} onClick={() => void enter()}>
              Unlock
            </Button>
          </Box>
          {message && (
            <Typography variant="body2" color="error" sx={{ mt: 1 }}>
              {message}
            </Typography>
          )}
          <Button variant="text" size="small" sx={{ mt: 1, textTransform: 'none' }} onClick={reset}>
            Reset password on this device
          </Button>
        </Box>
      ) : (
        <Box>
          <Typography variant="body1" gutterBottom>
            Set your administrator password
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            First time on this device: pick the password this door will ask for. Only a scrambled
            fingerprint of it is kept here — never the password itself.
          </Typography>
          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'flex-start' }}>
            <TextField
              size="small"
              type="password"
              label="New password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              inputProps={{ 'data-testid': 'admin-portal-set-password' }}
            />
            <TextField
              size="small"
              type="password"
              label="Type it again"
              value={confirm}
              onChange={e => setConfirm(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter' && password && confirm) void setAndEnter();
              }}
              inputProps={{ 'data-testid': 'admin-portal-set-confirm' }}
            />
            <Button
              variant="contained"
              disabled={busy || !password || !confirm}
              onClick={() => void setAndEnter()}
            >
              Set password
            </Button>
          </Box>
          {message && (
            <Typography variant="body2" color="error" sx={{ mt: 1 }}>
              {message}
            </Typography>
          )}
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            Setting it takes you straight in — and this door then stays unlocked for the rest of the
            visit.
          </Typography>
        </Box>
      )}
    </Paper>
  );
};

export default AdminPortalDoor;
