import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Box, Button, IconButton, Paper, TextField, Typography } from '@mui/material';
import { stageFighter } from '../utils/stageEvents';
import { useFavorites } from '../utils/favorites';
import { elementColor, elementEmoji } from '../utils/navitarArt';
import { NavitarSellAction, useOwnedNavitarRecord } from './SellNavitar';

// The Navidex DECK (Round 36.10 Part B, Eddie 2026-11-20 ~14:21
// PT): "stack the cards behind each other like a deck and just
// swipe them over to see the full card — scrolling all the way
// up and all the way down is not fun." The R36.9 vertical snap
// shelf is REMOVED (named removal — Eddie's order): in its place,
// below the Stage, the collection browses as ONE deck — a full
// uniform card in front (the same NavitarDesign the grids and
// the Stage render), the next cards stacked behind it with their
// edges peeking, swipe OR the ‹ › glass arrows to walk the deck,
// and a position line (12 / 116 — the player's own collection,
// allowed) with the section the front card belongs to.
//
// The front card is fully functional: its ✓ chooses, its ★
// favorites, its Card/3D toggle flips its own picture, and a tap
// on its body stages it (the R36.9 tap-to-stage path, moved here
// with the shelf's removal). The picker grids below stay the
// jump tool; the search above (Part C) is the other — type a
// name, tap the result, the deck walks straight to that card
// (and stages it, when it has a model, per the deck's own tap
// behaviour). The ★ Favorites chip cycles the deck through the
// player's favorites only.

export interface DeckEntry {
  name: string;
  element: string;
  epithet?: string;
  // The page section this card belongs to (its heading on the
  // page below) — shown as the deck's caption.
  section: string;
  node: React.ReactNode;
}

// Tap-to-stage (moved from the R36.9 shelf): a plain body tap on
// the front card stages that fighter — the Stage listens via
// utils/stageEvents. Taps on the art keep their cry, taps on any
// control keep their own behaviour; only body taps stage.
const deckTapToStage = (e: React.MouseEvent<HTMLDivElement>) => {
  const t = e.target as HTMLElement;
  if (t.closest('button, a, input, select, textarea, [role="button"], [role="dialog"]')) return;
  if (t.closest('img, canvas')) return;
  const nameEl = e.currentTarget.querySelector('[data-testid="card-overlay-name"]');
  const name = nameEl?.textContent?.trim();
  if (name) stageFighter(name);
};

const ARROW_SX = {
  position: 'absolute' as const,
  top: '50%',
  transform: 'translateY(-50%)',
  zIndex: 6,
  width: 38,
  height: 38,
  borderRadius: '50%',
  backgroundColor: 'rgba(8,20,28,0.55)',
  backdropFilter: 'blur(6px)',
  border: '1px solid rgba(255,255,255,0.35)',
  color: '#fff',
  fontSize: '1.3rem',
  lineHeight: 1,
  pb: '3px',
};

export const NavidexDeck: React.FC<{
  entries: DeckEntry[];
  // Fighters with a real 3D model (the Stage's roster): a search
  // jump stages these, exactly as a body tap on their card does.
  modeledNames: ReadonlySet<string>;
}> = ({ entries, modeledNames }) => {
  const favorites = useFavorites();
  const [favOnly, setFavOnly] = useState(false);
  const [index, setIndex] = useState(0);
  const [query, setQuery] = useState('');
  const [searchFocus, setSearchFocus] = useState(false);
  const outerRef = useRef<HTMLDivElement>(null);
  const viewportRef = useRef<HTMLDivElement>(null);

  const list = useMemo(
    () => (favOnly ? entries.filter(e => favorites.includes(e.name)) : entries),
    [favOnly, entries, favorites]
  );
  const safeIndex = Math.min(index, Math.max(list.length - 1, 0));
  const front = list[safeIndex];
  // Round 36.13 Part B: the front card's sell door (below) takes
  // layout space only when the front fighter is in the player's
  // own collection — an unowned front card leaves no gap.
  const frontOwned = useOwnedNavitarRecord(front?.name ?? '');

  const goToDeck = (next: number) => {
    if (list.length === 0) return;
    setIndex(((next % list.length) + list.length) % list.length);
  };

  // ---- Deck swipe (the Stage's gesture pattern, Round 7–9
  // lessons): pointer tracking with a direction lock, a native
  // non-passive touchmove guard so iOS Safari can't scroll-claim
  // a horizontal drag into a touchcancel, and a capture-phase
  // click swallow so a swipe that ends on a button never ALSO
  // fires that button. Vertical drags are released to page
  // scroll untouched. ----
  const lastSwipeNavAt = useRef(0);
  const gestureConsumed = useRef(false);
  const swipeGesture = useRef<{ x: number; y: number; lock: 'h' | 'v' | null } | null>(null);
  const beginSwipe = (x: number, y: number) => {
    swipeGesture.current = { x, y, lock: null };
    gestureConsumed.current = false;
  };
  const trackSwipe = (x: number, y: number): number | null => {
    const g = swipeGesture.current;
    if (!g) return null;
    const dx = x - g.x;
    const dy = y - g.y;
    if (!g.lock) {
      if (Math.abs(dx) < 10 && Math.abs(dy) < 10) return null;
      g.lock = Math.abs(dx) > Math.abs(dy) ? 'h' : 'v';
    }
    return g.lock === 'h' ? dx : null;
  };
  const endSwipe = (x: number) => {
    const g = swipeGesture.current;
    swipeGesture.current = null;
    if (!g || gestureConsumed.current) return;
    gestureConsumed.current = true;
    const dx = x - g.x;
    if (g.lock === 'h' && Math.abs(dx) > 48) {
      lastSwipeNavAt.current = Date.now();
      goToDeck(safeIndex + (dx < 0 ? 1 : -1));
    }
  };
  useEffect(() => {
    const el = viewportRef.current;
    if (!el) return;
    const onMove = (e: TouchEvent) => {
      const g = swipeGesture.current;
      if (!g) return;
      const t = e.touches[0];
      if (!t) return;
      if (trackSwipe(t.clientX, t.clientY) !== null && e.cancelable) e.preventDefault();
    };
    const onClickCapture = (e: MouseEvent) => {
      if (Date.now() - lastSwipeNavAt.current < 350) {
        e.preventDefault();
        e.stopPropagation();
      }
    };
    el.addEventListener('touchmove', onMove, { passive: false });
    el.addEventListener('click', onClickCapture, true);
    return () => {
      el.removeEventListener('touchmove', onMove);
      el.removeEventListener('click', onClickCapture, true);
    };
  }, []);

  // ---- Search (Part C): name first; element and epithet ride
  // along as secondary matches. ----
  const q = query.trim().toLowerCase();
  const matches = useMemo(() => {
    if (!q) return [];
    return entries
      .filter(
        e =>
          e.name.toLowerCase().includes(q) ||
          e.element.toLowerCase() === q ||
          (e.epithet ? e.epithet.toLowerCase().includes(q) : false)
      )
      .slice(0, 8);
  }, [q, entries]);

  const jumpTo = (entry: DeckEntry) => {
    let target = list;
    if (favOnly && !favorites.includes(entry.name)) {
      setFavOnly(false);
      target = entries;
    }
    const i = target.findIndex(e => e.name === entry.name);
    if (i >= 0) setIndex(i);
    setQuery('');
    if (modeledNames.has(entry.name)) stageFighter(entry.name);
    outerRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  if (entries.length === 0) return null;

  return (
    <Box ref={outerRef} data-testid="navidex-deck" sx={{ mb: 5, overflowX: 'clip' }}>
      {/* Toolbar: search + the favorites switch (Part C). */}
      <Box
        sx={{
          position: 'relative',
          display: 'flex',
          gap: 1,
          alignItems: 'flex-start',
          maxWidth: 520,
          mx: 'auto',
          mb: 1.5,
        }}
      >
        <Box sx={{ flex: 1, position: 'relative' }}>
          <TextField
            data-testid="navidex-search-input"
            size="small"
            fullWidth
            value={query}
            placeholder="Search your Navidex…"
            aria-label="Search your Navidex"
            onChange={e => setQuery(e.target.value)}
            onFocus={() => setSearchFocus(true)}
            onBlur={() => window.setTimeout(() => setSearchFocus(false), 150)}
            onKeyDown={e => {
              if (e.key === 'Enter' && matches.length > 0) {
                e.preventDefault();
                jumpTo(matches[0]);
              }
            }}
          />
          {q && searchFocus && (
            <Paper
              elevation={8}
              sx={{
                position: 'absolute',
                top: 'calc(100% + 4px)',
                left: 0,
                right: 0,
                zIndex: 30,
                overflow: 'hidden',
              }}
            >
              {matches.length === 0 ? (
                <Typography variant="body2" sx={{ px: 2, py: 1.25, color: 'text.secondary' }}>
                  No navitar matches “{query.trim()}”
                </Typography>
              ) : (
                matches.map(m => (
                  <Button
                    key={m.name}
                    data-testid="navidex-search-result"
                    data-name={m.name}
                    fullWidth
                    onMouseDown={e => {
                      e.preventDefault();
                      jumpTo(m);
                    }}
                    onClick={() => {
                      // Keyboard activation (Enter/Space on the
                      // focused result) fires click WITHOUT a
                      // preceding mousedown — jump then. After a
                      // real mousedown the jump already ran and
                      // cleared the query, so this no-ops.
                      if (query) jumpTo(m);
                    }}
                    sx={{
                      justifyContent: 'flex-start',
                      textTransform: 'none',
                      color: 'text.primary',
                      px: 2,
                      py: 1,
                    }}
                  >
                    <span style={{ marginRight: 8 }}>{elementEmoji(m.element)}</span>
                    <span style={{ fontWeight: 700 }}>{m.name}</span>
                    <span style={{ marginLeft: 'auto', opacity: 0.6, fontSize: '0.75rem' }}>
                      {m.section}
                    </span>
                  </Button>
                ))
              )}
            </Paper>
          )}
        </Box>
        <Button
          data-testid="navidex-favorites-toggle"
          aria-pressed={favOnly}
          variant={favOnly ? 'contained' : 'outlined'}
          onClick={() => {
            setFavOnly(v => !v);
            setIndex(0);
          }}
          sx={{
            textTransform: 'none',
            fontWeight: 800,
            whiteSpace: 'nowrap',
            color: favOnly ? '#4a3500' : undefined,
            bgcolor: favOnly ? '#ffd54f' : undefined,
            borderColor: 'rgba(255,213,79,0.7)',
            '&:hover': { bgcolor: favOnly ? '#ffca28' : 'rgba(255,213,79,0.12)' },
          }}
        >
          ★ Favorites{favorites.length > 0 ? ` (${favorites.length})` : ''}
        </Button>
      </Box>

      {favOnly && list.length === 0 ? (
        <Box
          data-testid="navidex-favorites-empty"
          sx={{
            maxWidth: 520,
            mx: 'auto',
            textAlign: 'center',
            py: 4,
            px: 2,
            borderRadius: 3,
            border: '1px dashed rgba(140,170,185,0.5)',
          }}
        >
          <Typography variant="body1" sx={{ mb: 1 }}>
            No favorites yet — tap ★ on a card
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Your favorites gather here, one tap away in the deck.
          </Typography>
        </Box>
      ) : (
        front && (
          <>
            {/* Section + position: where the front card lives,
                and where the player stands in the deck. */}
            <Box
              sx={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'baseline',
                maxWidth: {
                  xs: '100%',
                  sm: 'calc((100% - 24px) / 2)',
                  md: 'calc((100% - 48px) / 3)',
                },
                mx: 'auto',
                mb: 0.75,
                px: 0.5,
              }}
            >
              <Typography
                data-testid="navidex-deck-section"
                variant="caption"
                sx={{
                  fontWeight: 800,
                  letterSpacing: '0.06em',
                  color: 'text.secondary',
                  textTransform: 'uppercase',
                }}
              >
                {front.section}
              </Typography>
              <Typography
                data-testid="navidex-deck-position"
                variant="caption"
                sx={{ fontWeight: 800, color: 'text.secondary' }}
              >
                {safeIndex + 1} / {list.length}
              </Typography>
            </Box>
            {/* The stack: front card in flow, the next two cards
                peeking behind it (real cards, inert), arrows at
                the front card's edges. */}
            <Box
              ref={viewportRef}
              data-testid="navidex-deck-viewport"
              onPointerDown={e => beginSwipe(e.clientX, e.clientY)}
              onPointerMove={e => trackSwipe(e.clientX, e.clientY)}
              onPointerUp={e => endSwipe(e.clientX)}
              onPointerCancel={() => {
                swipeGesture.current = null;
              }}
              onTouchEnd={e => {
                if (swipeGesture.current) endSwipe(e.changedTouches[0].clientX);
              }}
              sx={{
                position: 'relative',
                width: { xs: '100%', sm: 'calc((100% - 24px) / 2)', md: 'calc((100% - 48px) / 3)' },
                mx: 'auto',
                // Room for the stack's peek below (16px down)
                // inside the page flow; the right peek overflows
                // into the deck box's slack and is clipped at
                // the page edge by the outer box's overflowX —
                // the front card keeps the grid twin's EXACT
                // width (the R25 uniformity law).
                mb: '18px',
              }}
            >
              {[2, 1].map(k => {
                const behind = list.length > k ? list[(safeIndex + k) % list.length] : null;
                if (!behind) return null;
                const tint = elementColor(behind.element);
                return (
                  <Box
                    key={`${behind.name}-${k}`}
                    aria-hidden
                    data-deck-behind={behind.name}
                    sx={{
                      position: 'absolute',
                      inset: 0,
                      transform: `translate(${k * 10}px, ${k * 8}px) scale(${1 - k * 0.03})`,
                      transformOrigin: 'top left',
                      // A card SILHOUETTE, not the card itself:
                      // the uniform card's body is a translucent
                      // wash, so a real card face behind the
                      // front card ghosts its text straight
                      // through (proven on this round's first
                      // screenshots). What a physical deck shows
                      // is EDGES — so the slab wears the next
                      // fighter's own element tint + frame ring
                      // over an opaque paper base, and nothing
                      // else. You can see whose elements are
                      // coming; no face bleeds.
                      background: `linear-gradient(165deg, ${tint}59 0%, ${tint}2b 46%, rgba(140,170,185,0.18) 82%)`,
                      backgroundColor: 'background.paper',
                      borderRadius: '16px',
                      boxShadow: `0 0 0 3px ${tint}d9, 0 10px 26px rgba(0,0,0,0.25)`,
                      filter: `brightness(${k === 1 ? 0.9 : 0.78})`,
                      pointerEvents: 'none',
                      zIndex: 3 - k,
                    }}
                  />
                );
              })}
              <Box
                data-testid="navidex-deck-front"
                data-name={front.name}
                onClick={deckTapToStage}
                sx={{ position: 'relative', zIndex: 3 }}
              >
                {front.node}
              </Box>
              {list.length > 1 && (
                <>
                  <IconButton
                    data-testid="navidex-deck-prev"
                    aria-label="Previous card"
                    onClick={() => goToDeck(safeIndex - 1)}
                    sx={{ ...ARROW_SX, left: 6 }}
                  >
                    ‹
                  </IconButton>
                  <IconButton
                    data-testid="navidex-deck-next"
                    aria-label="Next card"
                    onClick={() => goToDeck(safeIndex + 1)}
                    sx={{ ...ARROW_SX, right: 6 }}
                  >
                    ›
                  </IconButton>
                </>
              )}
            </Box>
            {/* SELL (Round 36.13 Part B, Eddie 2026-11-21 ~08:58
                PT): the sell door on the deck front card — the
                same Round 19 flow as the Stage card's door
                (components/SellNavitar), for the fighter in
                front. It sits OUTSIDE the swipe viewport, so a
                tap on it never stages or swipes, and it renders
                only when the front fighter is owned. */}
            {frontOwned && (
              <Box
                sx={{
                  maxWidth: {
                    xs: '100%',
                    sm: 'calc((100% - 24px) / 2)',
                    md: 'calc((100% - 48px) / 3)',
                  },
                  mx: 'auto',
                  display: 'flex',
                  justifyContent: 'center',
                  mb: 1,
                }}
              >
                <NavitarSellAction name={front.name} testidPrefix="deck" />
              </Box>
            )}
          </>
        )
      )}
    </Box>
  );
};

export default NavidexDeck;
