import React, { Component, lazy, ReactNode, Suspense, useState } from 'react';
import { Box, CircularProgress, Typography } from '@mui/material';
import { NavitarArtImg } from './NavitarArtImg';
import { getCollectibleCard } from '../utils/collectibleCards';
import { elementColor, modelPresentationFor } from '../utils/navitarArt';

// The three.js renderer lives behind React.lazy so the (large) three.js
// code splits out of the main bundle and only loads when a 3D view is
// actually shown. A failure to load or mount it can never take the page
// down: the lazy import or the canvas render throws inside
// ModelErrorBoundary and the 2D art renders instead.
//
// NOTE: this deliberately does NOT use @react-three/fiber. Fiber 9 (via
// its `its-fine` dependency) statically references React.use, which
// React 18 does not export — importing fiber breaks the production build
// outright ("'use' is not exported from 'react'"). The viewer therefore
// uses plain three.js (see ModelCanvas), which compiles and runs on
// React 18. If the app ever moves to React 19, the viewer can be
// revisited — the ModelViewer props stay the same either way.
const ModelCanvas = lazy(() => import('./ModelCanvas'));

interface ErrorBoundaryProps {
  fallback: ReactNode;
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

class ModelErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error): void {
    console.warn('3D model failed to render, showing 2D art instead:', error);
  }

  render(): ReactNode {
    return this.state.hasError ? this.props.fallback : this.props.children;
  }
}

export interface ModelViewerProps {
  modelUrl: string;
  // Round 36.14: a companion model sharing the scene (the
  // Multiverse Bot's sphere drone) — passed through to ModelCanvas.
  companionUrl?: string;
  // 2D art shown while the GLB loads, and in place of the model if 3D
  // is unavailable. Absent for the griffin (no 2D art exists for it),
  // in which case the slot is a neutral placeholder.
  fallbackSrc?: string;
  fallbackAlt: string;
  element?: string;
  // Round 24: the fighter's name, when the caller knows it. While
  // the GLB loads, a fighter WITH a collectible card summons
  // through its card art instead of the portrait-and-veil;
  // fighters without a card keep the portrait treatment below.
  // (Round 36.5: the art stands bare at full slot size — no
  // dressed-card composite, no "Summoning…" pill over it.)
  fighterName?: string;
  height?: number | string;
  // Closer framing for wide-spanning models (the phoenix's wings).
  zoom?: number;
  // Grounded framing (feet planted, camera at mid-height) — used by
  // the AR view so the navitar stands on its ground shadow.
  grounded?: boolean;
}

// WebGL support probe (hardened 2026-11-16): the old check only
// tested that the WebGLRenderingContext CONSTRUCTOR exists — but an
// environment can define the constructor while refusing to create a
// context (GPU blocklists, domain/policy gates, headless software
// renderers), which sent the renderer down a throw-and-catch path.
// Probe for real: create a throwaway context and lose it
// immediately. Any failure (or jsdom, which has no WebGL at all)
// reads as "no 3D" and the caller renders the 2D art instead.
// Round 6: only a SUCCESS is cached — a probe that fails during a
// transient GPU/context crunch used to stick "no 3D" for the whole
// session and turn every card into a picture; a failure now simply
// re-probes on the next viewer mount.
let webglProbeOk = false;
function webglAvailable(): boolean {
  if (webglProbeOk) return true;
  try {
    if (typeof window === 'undefined' || typeof document === 'undefined') return false;
    const canvas = document.createElement('canvas');
    const gl = (canvas.getContext('webgl2') ||
      canvas.getContext('webgl')) as WebGLRenderingContext | null;
    if (gl) {
      gl.getExtension('WEBGL_lose_context')?.loseContext();
      webglProbeOk = true;
    }
  } catch {
    webglProbeOk = false;
  }
  return webglProbeOk;
}

export const ModelViewer: React.FC<ModelViewerProps> = ({
  modelUrl,
  companionUrl,
  fallbackSrc,
  fallbackAlt,
  element = 'ice',
  fighterName,
  height = 260,
  zoom = 1,
  grounded = false,
}) => {
  // One-shot gate: no WebGL, no Canvas attempt at all.
  const [canRender3d] = useState(() => webglAvailable());
  const [loaded, setLoaded] = useState(false);
  const [failed, setFailed] = useState(false);

  const fallback = fallbackSrc ? (
    <NavitarArtImg
      src={fallbackSrc}
      alt={fallbackAlt}
      element={element}
      fit="contain"
      style={{ width: '100%', height: '100%' }}
    />
  ) : (
    <Box
      sx={{
        width: '100%',
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'radial-gradient(circle at 50% 30%, #546e7a66, #121212 75%)',
        px: 2,
      }}
    >
      <Typography variant="body2" color="text.secondary" align="center">
        {fallbackAlt}
      </Typography>
    </Box>
  );

  // While the GLB itself downloads (17–22 MB) the slot shows the 2D art
  // under a "Loading 3D model…" veil, so it never reads as an empty box.
  // Round 24: a fighter with a collectible card SUMMONS through the
  // card instead — the card is light and lands instantly, the model
  // swaps in on load. The error/no-WebGL fallback is unchanged: the
  // 2D art (or the neutral placeholder) is what failure shows.
  // Round 36.5 (Eddie, 2026-11-19): the summoning state IS the
  // fighter's real collectible card art standing in the slot at
  // the slot's full size — the same picture the card view shows —
  // with NOTHING over it: the small "Summoning {name}…" pill and
  // the scaled-down dressed-card composite that used to ride here
  // are gone (the tiny unreadable card was Eddie's standing
  // irritation). The model still swaps in on load, once.
  const summonArt =
    fighterName && getCollectibleCard(fighterName) ? (
      <NavitarArtImg
        src={getCollectibleCard(fighterName) ?? ''}
        alt={`${fighterName} collectible card`}
        element={element}
        fit="contain"
        style={{ width: '100%', height: '100%' }}
      />
    ) : null;
  const loadingOverlay = summonArt ?? (
    <Box sx={{ position: 'relative', width: '100%', height: '100%' }}>
      {fallback}
      <Box
        sx={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          bgcolor: 'rgba(0,0,0,0.45)',
        }}
      >
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <CircularProgress size={20} />
          <Typography variant="body2">Loading 3D model…</Typography>
        </Box>
      </Box>
    </Box>
  );

  return (
    <Box
      sx={{
        width: '100%',
        height,
        position: 'relative',
        overflow: 'hidden',
        borderRadius: '16px',
      }}
    >
      {canRender3d && !failed ? (
        <ModelErrorBoundary fallback={fallback}>
          <Suspense fallback={loadingOverlay}>
            <ModelCanvas
              modelUrl={modelUrl}
              companionUrl={companionUrl}
              zoom={zoom}
              grounded={grounded}
              baseTint={elementColor(element)}
              ripple={element === 'water'}
              rotationY={modelPresentationFor(modelUrl).rotationY}
              sinkFrac={modelPresentationFor(modelUrl).sinkFrac}
              onLoaded={() => setLoaded(true)}
              onError={() => setFailed(true)}
            />
          </Suspense>
          {!loaded && <Box sx={{ position: 'absolute', inset: 0 }}>{loadingOverlay}</Box>}
        </ModelErrorBoundary>
      ) : (
        fallback
      )}
    </Box>
  );
};
