// Notifications home (Round 17, Eddie 2026-11-17) — "a place where
// your notifications are showed that you can click on and say ok
// go over here and check what's going on."
//
// The pop-ups (components/NotificationToasts.tsx) go down fast by
// design; THIS page is where every notification lives afterwards.
// The top-bar bell (with its unread badge) lands here. Newest
// first; unread records stand out with a dot and a lit surface;
// tapping any record marks it read and takes the player to the
// thing it points at — a venue on the map, a person's meet card, a
// friend's row — via NotificationsContext.activate(). No dead
// ends, and an honest empty state when there's nothing yet.
import React from 'react';
import { Box, Button, Chip, Container, Paper, Typography } from '@mui/material';
import DoneAllIcon from '@mui/icons-material/DoneAll';
import { useNotifications } from '../contexts/NotificationsContext';
import type { NotificationKind } from '../utils/notifications';

const KIND_EMOJI: Record<NotificationKind, string> = {
  venue: '📍',
  icebreaker: '💬',
  friend: '🤝',
  suggestion: '✨',
  message: '💬',
  event: '📅',
  fighter: '✔️',
};

function timeAgo(ts: number): string {
  const mins = Math.floor((Date.now() - ts) / 60000);
  if (mins < 1) return 'Just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  return new Date(ts).toLocaleDateString();
}

const Notifications: React.FC = () => {
  const { notifications, unreadCount, markAllRead, activate } = useNotifications();

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="notifications-page">
      <Typography variant="h4" gutterBottom align="center">
        Notifications
      </Typography>
      <Typography variant="body1" color="text.secondary" align="center" sx={{ mb: 3 }}>
        Everything your navitar, your friends and the venues have flagged for you — kept here after
        the pop-ups go down. Tap one to go straight to it. Message notifications only ever say the
        type — the words themselves live in your Inbox, never here.
      </Typography>

      {unreadCount > 0 && (
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 2 }}>
          <Button
            variant="outlined"
            size="small"
            startIcon={<DoneAllIcon />}
            onClick={markAllRead}
            data-testid="notifications-mark-all-read"
          >
            Mark all read ({unreadCount})
          </Button>
        </Box>
      )}

      {notifications.length === 0 ? (
        <Paper sx={{ p: 4, textAlign: 'center' }} data-testid="notifications-empty">
          <Typography variant="h6" gutterBottom>
            🔔 Nothing here yet
          </Typography>
          <Typography variant="body2" color="text.secondary">
            When your navitar spots someone at a venue, a venue runs something, or a friend answers
            a request, it lands here — and pops up in the corner when it happens.
          </Typography>
        </Paper>
      ) : (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
          {notifications.map(n => (
            <Paper
              key={n.id}
              data-testid="notification-item"
              data-notification-id={n.id}
              data-kind={n.kind}
              data-read={n.read ? 'true' : 'false'}
              onClick={() => activate(n)}
              sx={{
                p: 2,
                display: 'flex',
                gap: 1.5,
                alignItems: 'flex-start',
                cursor: 'pointer',
                borderLeft: n.read ? '4px solid transparent' : '4px solid',
                borderColor: n.read ? 'transparent' : 'primary.main',
                bgcolor: n.read ? undefined : 'rgba(18,165,199,0.07)',
              }}
            >
              <Box
                sx={{
                  width: 38,
                  height: 38,
                  borderRadius: '50%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '1.1rem',
                  flexShrink: 0,
                  bgcolor: 'rgba(18, 165, 199, 0.15)',
                }}
              >
                {KIND_EMOJI[n.kind]}
              </Box>
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                  <Typography variant="subtitle2" sx={{ fontWeight: n.read ? 600 : 800 }}>
                    {n.title}
                  </Typography>
                  {!n.read && (
                    <Box
                      sx={{
                        width: 8,
                        height: 8,
                        borderRadius: '50%',
                        bgcolor: 'secondary.main',
                        flexShrink: 0,
                      }}
                    />
                  )}
                </Box>
                <Typography variant="body2" color="text.secondary">
                  {n.body}
                </Typography>
                <Box sx={{ display: 'flex', gap: 1, mt: 0.75, alignItems: 'center' }}>
                  <Typography variant="caption" color="text.secondary">
                    {timeAgo(n.createdAt)}
                  </Typography>
                  {n.demo && (
                    <Chip size="small" variant="outlined" label="DEMO" sx={{ height: 18 }} />
                  )}
                </Box>
              </Box>
            </Paper>
          ))}
        </Box>
      )}
    </Container>
  );
};

export default Notifications;
