// Helpdesk outbox (Round 36, Eddie 2026-11-18 ~11:19 + the
// confirmation rule ~15:11 PT): ALL help goes through the
// navitar. The navitar drafts the player's request, shows it
// back verbatim, and a request is recorded ONLY when the player
// taps Send on that show-back. Cancel — or simply ignoring the
// draft — kills it: nothing is stored, nothing is sent.
//
// DEMO HONESTY: in this preview the outbox is this device's
// localStorage (glacer-helpdesk). No support team receives
// anything yet, and the in-chat confirmation says exactly that.
// When the live helpdesk wires in (Phase 2), confirmed requests
// leave through here — the show-back + confirm law does not
// change.

export const HELPDESK_KEY = 'glacer-helpdesk';

export interface HelpdeskRequest {
  id: string;
  // The exact text the player was shown and confirmed.
  text: string;
  ts: number;
}

export function loadHelpdeskRequests(): HelpdeskRequest[] {
  try {
    const raw = localStorage.getItem(HELPDESK_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as HelpdeskRequest[];
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      r => r && typeof r.id === 'string' && typeof r.text === 'string' && Number.isFinite(r.ts)
    );
  } catch {
    return [];
  }
}

export function addHelpdeskRequest(text: string): HelpdeskRequest {
  const record: HelpdeskRequest = {
    id: `help-${Date.now()}-${Math.floor(Math.random() * 1e6)}`,
    text,
    ts: Date.now(),
  };
  try {
    localStorage.setItem(HELPDESK_KEY, JSON.stringify([...loadHelpdeskRequests(), record]));
  } catch {
    // Storage unavailable — the record holds for this call only;
    // the chat still confirms what the player confirmed.
  }
  return record;
}
