import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Box, Button, Chip, Container, Paper, TextField, Typography } from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import { PersonStatusChip } from '../components/NetworkingStatus';
import { PlayerAvatar } from '../components/PlayerAvatar';
import { useNotifications } from '../contexts/NotificationsContext';
import { usePresence } from '../contexts/PresenceContext';
import { useVenue } from '../contexts/VenueContext';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { saveChallengeHandoff } from '../utils/challengeHandoff';
import { loadFriends } from '../utils/friends';
import { matchReasonFor, type MatchReason } from '../utils/presence';
import {
  GROUP_CHAT_REPLIES,
  SOCIAL_CHANGED_EVENT,
  acceptIncomingRequest,
  allDemoPeople,
  declineIncomingRequest,
  demoAccepts,
  demoHandle,
  demoPersonByHandle,
  loadSocial,
  resolveFriendRequest,
  saveSocial,
  type DemoGroup,
  type SocialState,
} from '../utils/social';
import {
  EMPTY_MODERATION,
  REMOVED_PLACEHOLDER,
  activeKeys,
  appointModerator,
  groupSpaceId,
  muteParticipant,
  pinMessage,
  postRenders,
  postableKeys,
  removeMessage,
  removeParticipant,
  roleInSpace,
  setLocked,
  unappointModerator,
  unmuteParticipant,
  unpinMessage,
} from '../utils/moderation';
import {
  LockedBanner,
  ModBadge,
  PinnedArea,
  SystemLineRow,
  mergeFlow,
  useSpaceModeration,
} from '../components/Moderation';
import { MessageModMenu, ParticipantsPanel } from '../components/ModerationLazy';

// Friends — the demo social layer (Option C preview build, Eddie
// 2026-11-16; spec: social-friends-groups-navitar-suggestions-spec.md).
//
// HONEST FRAMING: everything here is a single-device demo. The
// people are the game's demo personas, their answers are simulated
// on this device, and state persists in localStorage only. Real
// cross-player friends, groups and chats are Phase 2.
//
// The laws, visibly enforced:
// - Friend requests: nobody is added without accepting. An accept
//   lands the person in the real glacer-friends list (Profile +
//   World Map friend pins read it); a decline is polite and final,
//   handled gracefully by the navitar.
// - Groups are player-made and player-run; invites are
//   accept/decline, members only ever see the group if they said yes.
// - Group chats: one per group, plus chat-first threads started
//   straight from a friend selection. Anyone can leave. Navitars
//   wingman only when the player's presence allows (Just here /
//   Invisible = the navitar stays out).
// - Navitar suggestions: the navitar SUGGESTS, naming the reason and
//   the context. The human approves or passes FIRST; only then does
//   the other side get asked (simulated), and only a yes on both
//   sides makes an introduction. Never auto-connect, never a forced
//   chat or battle. Dating suggestions exist only on mutual opt-in
//   (the presence "here for dating" setting, OFF by default) and are
//   never shown to anyone who hasn't opted in.
// - Blocking is total: no requests, suggestions, challenges or chat.
// - Safety without being nosy: flag-and-notify only — "that's not
//   how we operate here" — and no records are kept on people.
//
// Round 26 (Eddie 2026-11-18) — the second door: ADD BY USERNAME.
// Running into someone (the map icebreaker) is no longer the only
// way to start a friendship: type a demo handle (@maya) and the
// request rides the SAME `requests` record, the SAME simulated
// answer, and the SAME accept write as the list below. Demo people
// also send requests TO the player now (seeded once per device by
// IncomingRequestProducer, announced type-only — type + sender,
// nothing else): the Incoming section sits high on this page so a
// notification tap lands with it in view, and accepting one writes
// the same one friends list everything else reads.

const CONTEXT_LABEL: Record<MatchReason['kind'], string> = {
  business: 'Business',
  interest: 'Networking interests',
  dating: 'Dating',
};

// The group-chat reply bank moved to utils/social.ts (Round 22)
// as GROUP_CHAT_REPLIES — the Inbox group conversation answers
// from the same bank, so a group never replies in two voices.

const Friends: React.FC = () => {
  const { networkingStatus, visibility, hereForDating, businessName, businessIndustry, interests } =
    usePresence();
  const { checkedInVenueId } = useVenue();
  const { addVenueOpponent } = useNavitarFightClub();
  const { notify } = useNotifications();
  const navigate = useNavigate();

  // ⚔️ Battle on a friend (Round 10): direct, like every meet
  // surface — their navitar becomes a challengeable opponent (the
  // shared venue adder, so the record is the same one the map's
  // meet card creates), the handoff carries the pairing + this page
  // as the return surface, and the challenge screen takes it from
  // there. This replaces the old "Challenge from Profile →" link,
  // which sent friend battles to a different system's page.
  const battleFriend = (person: (typeof people)[number]['person']) => {
    const opponentInput = {
      name: person.navitarName,
      element: person.navitarElement,
      level: person.navitarLevel,
      skills: person.navitarSkills,
      imageUrl: person.navitarImage,
      modelUrl: person.navitarModelUrl,
      modelZoom: person.navitarModelZoom,
    };
    const opponentId = addVenueOpponent(opponentInput);
    if (!opponentId) return;
    saveChallengeHandoff({
      opponentId,
      opponent: opponentInput,
      kind: 'venue',
      personName: person.name,
      venueId: '',
      sourceLabel: 'Friends',
      returnTo: '/friends',
      demo: true,
      directStart: false,
      ts: Date.now(),
    });
    navigate('/challenge');
  };

  const [social, setSocial] = useState<SocialState>(() => loadSocial());
  const [friendTick, setFriendTick] = useState(0);
  const timers = useRef<number[]>([]);

  const update = (next: SocialState) => {
    setSocial(next);
    saveSocial(next);
  };

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms));
  };
  useEffect(
    () => () => {
      timers.current.forEach(t => window.clearTimeout(t));
    },
    []
  );

  const people = useMemo(() => allDemoPeople(), []);
  const friendIds = useMemo(() => loadFriends(), [friendTick]); // (friend list reloads when friendTick changes)
  const friendEntries = useMemo(
    () =>
      people.filter(e => friendIds.includes(e.person.id) && !social.blocked.includes(e.person.id)),
    [people, friendIds, social.blocked]
  );

  // Resolve a pending friend request AND announce the answer
  // (Round 17): the answer used to land silently — if you weren't
  // staring at this page you never learned it. Now it writes a
  // notification (corner toast + the permanent home), so "X
  // accepted" reaches you wherever you are. Resolution reads the
  // persisted state (every mutation on this page saves it, so
  // storage and state are the same record) and runs the exact
  // simulated answer resolveFriendRequest always ran.
  const resolveRequestWithNotice = (personId: string) => {
    const current = loadSocial();
    if (current.requests[personId] !== 'pending') return;
    const { state, accepted } = resolveFriendRequest(current, personId);
    saveSocial(state);
    setSocial(state);
    setFriendTick(t => t + 1);
    const name = people.find(e => e.person.id === personId)?.person.name ?? 'Someone';
    notify({
      id: `friend-result-${personId}-${Date.now()}`,
      kind: 'friend',
      title: accepted
        ? `🤝 ${name} accepted your friend request`
        : `${name} passed on your friend request`,
      body: accepted
        ? `${name} is your friend now — battle them from here, invite them to groups, or say hi from Messages.`
        : 'Your navitar kept it graceful — the door stays closed, politely.',
      route: '/friends',
      personId,
      demo: true,
    });
  };

  // Resolve any requests left pending (e.g. the page was closed
  // mid-simulation) shortly after mount.
  useEffect(() => {
    const pending = Object.entries(social.requests).filter(([, s]) => s === 'pending');
    pending.forEach(([personId], i) => {
      later(() => resolveRequestWithNotice(personId), 900 + i * 400);
    });
    // Mount-only by design (the original effect's contract): the
    // pending set is read from the state this mount loaded with.
  }, []);

  // Round 26: the IncomingRequestProducer seeds the demo's
  // incoming requests at app level, possibly while this page is
  // already open. The social store announces every save on
  // SOCIAL_CHANGED_EVENT (the same signal the Inbox rides), so
  // reload on it and the Incoming section appears live. This
  // page's own saves re-fire it too — reloading the same record
  // is a no-op.
  useEffect(() => {
    const onChanged = () => setSocial(loadSocial());
    window.addEventListener(SOCIAL_CHANGED_EVENT, onChanged);
    return () => window.removeEventListener(SOCIAL_CHANGED_EVENT, onChanged);
  }, []);

  const suggestionsOff =
    social.suggestionFreq === 'off' || networkingStatus === 'quiet' || visibility === 'invisible';

  const suggestionCandidates = useMemo(() => {
    if (suggestionsOff) return [];
    const settings = {
      networkingStatus,
      visibility,
      hereForBusiness: true,
      hereForNetworking: true,
      hereForDating,
      businessName,
      businessIndustry,
      interests,
    };
    const scored = people
      .filter(
        e =>
          !friendIds.includes(e.person.id) &&
          !social.blocked.includes(e.person.id) &&
          !social.suggestions[e.person.id] &&
          e.person.networkingStatus !== 'quiet'
      )
      .map(e => {
        const real = matchReasonFor(e.person, settings);
        const reason: MatchReason =
          real ??
          ({
            kind: 'interest',
            label: `Same circuit — ${e.venueName}`,
            detail: `You and ${e.person.name} both spend time at ${e.venueName} — same room, same game.`,
          } as MatchReason);
        return { entry: e, reason, tier: real ? 0 : 1 };
      });
    if (social.suggestionFreq === 'venues') {
      if (!checkedInVenueId) return [];
      return scored
        .filter(s => s.entry.venueId === checkedInVenueId)
        .sort((a, b) => a.tier - b.tier)
        .slice(0, 4);
    }
    return scored.sort((a, b) => a.tier - b.tier).slice(0, 4);
  }, [
    people,
    friendIds,
    social.blocked,
    social.suggestions,
    suggestionsOff,
    social.suggestionFreq,
    checkedInVenueId,
    hereForDating,
    businessIndustry,
    interests,
    networkingStatus,
    visibility,
  ]);

  const sendRequest = (personId: string) => {
    update({ ...social, requests: { ...social.requests, [personId]: 'pending' } });
    later(() => resolveRequestWithNotice(personId), 1400);
  };

  // ---- Incoming requests (Round 26) -------------------------------
  const incomingPending = useMemo(
    () =>
      people.filter(
        e => social.incoming[e.person.id] === 'pending' && !social.blocked.includes(e.person.id)
      ),
    [people, social.incoming, social.blocked]
  );

  const acceptIncoming = (personId: string) => {
    const next = acceptIncomingRequest(loadSocial(), personId);
    setSocial(next);
    saveSocial(next);
    setFriendTick(t => t + 1);
  };

  const declineIncoming = (personId: string) => {
    const next = declineIncomingRequest(loadSocial(), personId);
    setSocial(next);
    saveSocial(next);
  };

  // ---- Add by username (Round 26) ---------------------------------
  const [usernameInput, setUsernameInput] = useState('');
  const [usernameResult, setUsernameResult] = useState<string | null>(null);

  const submitUsername = () => {
    const entry = demoPersonByHandle(usernameInput);
    if (!entry) {
      setUsernameResult(
        'No player with that username in the demo — demo handles are the demo people’s first names (like @maya). Real player usernames arrive in Phase 2.'
      );
      return;
    }
    const personId = entry.person.id;
    const handle = demoHandle(entry.person);
    if (social.blocked.includes(personId)) {
      setUsernameResult(
        `You’ve blocked ${handle} — a blocked person can’t be requested. Unblock them from their card in the list below first.`
      );
      return;
    }
    if (friendIds.includes(personId)) {
      setUsernameResult(`${handle} (${entry.person.name}) is already your friend.`);
      return;
    }
    if (social.incoming[personId] === 'pending') {
      setUsernameResult(
        `${handle} already sent YOU a request — answer it in Incoming requests above.`
      );
      return;
    }
    if (social.requests[personId] === 'pending') {
      setUsernameResult(`Request to ${handle} is already sent — waiting on ${entry.person.name}…`);
      return;
    }
    if (social.requests[personId] === 'declined') {
      setUsernameResult(`${handle} passed on a request before — the door stays closed, politely.`);
      return;
    }
    sendRequest(personId);
    setUsernameResult(
      `Request sent to ${handle} (${entry.person.name}, at ${entry.venueName}) — they’ll answer shortly. Answers are simulated in the demo.`
    );
  };

  const toggleBlock = (personId: string) => {
    const blocked = social.blocked.includes(personId)
      ? social.blocked.filter(id => id !== personId)
      : [...social.blocked, personId];
    update({ ...social, blocked });
  };

  const approveSuggestion = (personId: string, reasonDetail: string) => {
    update({ ...social, suggestions: { ...social.suggestions, [personId]: 'waiting' } });
    later(() => {
      // Same resolution the state updater used to run, computed on
      // the persisted state so a successful introduction can also
      // be announced (Round 17) — a "yes" from the other side is
      // news; a pass stays an in-page outcome only, no noise.
      const current = loadSocial();
      if (current.suggestions[personId] !== 'waiting') return;
      const accepted = demoAccepts(`suggestion:${personId}`);
      const entry = people.find(e => e.person.id === personId);
      const next: SocialState = {
        ...current,
        suggestions: {
          ...current.suggestions,
          [personId]: accepted ? 'introduced' : 'declined',
        },
        introductions: accepted
          ? [
              ...current.introductions,
              {
                personId,
                text: `Your navitars did the warm-up, then the wingman intro: “You two should know each other — ${reasonDetail}” Say hi any time from Messages or meet at ${entry?.venueName ?? 'a venue'} — a conversation, never a forced battle.`,
                ts: Date.now(),
              },
            ]
          : current.introductions,
      };
      saveSocial(next);
      setSocial(next);
      if (accepted) {
        notify({
          id: `suggestion-result-${personId}-${Date.now()}`,
          kind: 'suggestion',
          title: '✨ Your navitars made an introduction',
          body: `You and ${entry?.person.name ?? 'someone'} should know each other — ${reasonDetail} Say hi from Messages or meet at ${entry?.venueName ?? 'a venue'}.`,
          route: '/friends',
          personId,
          demo: true,
        });
      }
    }, 1300);
  };

  const passSuggestion = (personId: string) => {
    update({ ...social, suggestions: { ...social.suggestions, [personId]: 'passed' } });
  };

  // ---- Groups + group chats --------------------------------------
  const [groupName, setGroupName] = useState('');
  const [groupPicks, setGroupPicks] = useState<string[]>([]);
  const [chatPicks, setChatPicks] = useState<string[]>([]);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [draft, setDraft] = useState('');
  const [groupNote, setGroupNote] = useState<string | null>(null);

  const wingmanActive = networkingStatus === 'open' && visibility !== 'invisible';

  const createGroup = (kind: 'group' | 'chat', picks: string[], name: string) => {
    if (picks.length === 0) return;
    const memberIds: string[] = [];
    const declinedIds: string[] = [];
    for (const pid of picks) {
      (demoAccepts(`${kind}:${name}:${pid}`) ? memberIds : declinedIds).push(pid);
    }
    const group: DemoGroup = {
      id: `group-${Date.now()}`,
      name,
      kind,
      memberIds,
      declinedIds,
      left: false,
      messages: wingmanActive
        ? [
            {
              from: 'navitar',
              text:
                kind === 'group'
                  ? 'Your navitar set the room up and introduced everyone who accepted. Wingman mode: on.'
                  : 'Your navitar opened the chat for everyone who accepted. Wingman mode: on.',
              ts: Date.now(),
            },
          ]
        : [],
      createdAt: Date.now(),
    };
    update({ ...social, groups: [group, ...social.groups] });
    setActiveGroupId(group.id);
    setGroupNote(
      memberIds.length > 0
        ? `${memberIds.length} accepted right away${
            declinedIds.length
              ? ` · ${declinedIds.length} passed this time (no hard feelings — invites are always a choice)`
              : ''
          }.`
        : 'Everyone passed this time — nobody is added without a yes, so the room stays empty until someone accepts.'
    );
  };

  const activeGroup = social.groups.find(g => g.id === activeGroupId) ?? null;

  // Moderation (Round 35): every group the player made is a space
  // they own. The hook tracks the ACTIVE group's record (the
  // Inbox door writes the same record); the map feeds the group
  // cards' member lines for the rest.
  const {
    mod: groupMod,
    map: modMap,
    update: updateGroupMod,
  } = useSpaceModeration(activeGroup ? groupSpaceId(activeGroup.id) : null);

  const sendGroupMessage = () => {
    if (!activeGroup || !draft.trim() || activeGroup.left) return;
    // Round 35: a locked group refuses new posts.
    if (groupMod.locked) return;
    const groupId = activeGroup.id;
    const withMine: DemoGroup = {
      ...activeGroup,
      messages: [...activeGroup.messages, { from: 'you', text: draft.trim(), ts: Date.now() }],
    };
    update({ ...social, groups: social.groups.map(g => (g.id === groupId ? withMine : g)) });
    setDraft('');
    // Round 35: the reply comes from a member who can still post
    // here — muted and removed members never answer.
    const responder = postableKeys(
      groupMod,
      activeGroup.memberIds.map(id => `person:${id}`)
    )
      .map(k => people.find(e => e.person.id === k.slice('person:'.length))?.person)
      .find(Boolean);
    if (responder) {
      later(() => {
        setSocial(prev => {
          const g = prev.groups.find(x => x.id === groupId);
          if (!g || g.left) return prev;
          const reply = GROUP_CHAT_REPLIES[Math.floor(Math.random() * GROUP_CHAT_REPLIES.length)];
          const next: SocialState = {
            ...prev,
            groups: prev.groups.map(x =>
              x.id === groupId
                ? {
                    ...x,
                    messages: [
                      ...x.messages,
                      { from: 'them', author: responder.name, text: reply, ts: Date.now() },
                    ],
                  }
                : x
            ),
          };
          saveSocial(next);
          return next;
        });
      }, 1000);
    }
  };

  const leaveGroup = (groupId: string) => {
    update({
      ...social,
      groups: social.groups.map(g => (g.id === groupId ? { ...g, left: true } : g)),
    });
  };

  const pickChips = (picks: string[], setPicks: (next: string[]) => void, testPrefix: string) => (
    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
      {friendEntries.length === 0 && (
        <Typography variant="body2" color="text.secondary">
          No friends yet — accept a friend request below first, then they show up here.
        </Typography>
      )}
      {friendEntries.map(({ person }) => (
        <Chip
          key={person.id}
          label={person.name}
          clickable
          color={picks.includes(person.id) ? 'primary' : 'default'}
          data-testid={`${testPrefix}-${person.id}`}
          onClick={() =>
            setPicks(
              picks.includes(person.id)
                ? picks.filter(id => id !== person.id)
                : [...picks, person.id]
            )
          }
        />
      ))}
    </Box>
  );

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="friends-page">
      <Typography variant="h4" gutterBottom align="center">
        Friends &amp; Groups
      </Typography>
      <Paper sx={{ p: 2, mb: 3, bgcolor: 'rgba(232,145,45,0.12)' }}>
        <Typography variant="body2">
          🧪 <strong>Demo — on this device only.</strong> These are GLACER’s demo people; their
          answers are simulated here, and everything is saved in this browser. Real cross-player
          friends, groups and chats arrive in Phase 2. Conduct, everywhere on GLACER: safety without
          being nosy — if something looks off it gets flagged with a simple “that’s not how we
          operate here,” and no record is kept on anyone.
        </Typography>
      </Paper>

      {/* ---- Incoming requests (Round 26) -------------------------- */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="incoming-panel">
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center', mb: 1 }}>
          <Typography variant="h5">🤝 Incoming requests</Typography>
          <Chip size="small" label="DEMO" variant="outlined" />
        </Box>
        <Typography variant="body2" color="text.secondary" paragraph>
          Demo players can ask to be your friend too. Accepting adds them to the same friends list
          as everyone else — battle them, invite them to groups, say hi from Messages. Declining
          just clears the request, quietly.
        </Typography>
        {incomingPending.length === 0 ? (
          <Typography variant="body2" color="text.secondary" data-testid="incoming-empty">
            No incoming requests right now — when a demo player asks to be your friend, they’ll show
            up here.
          </Typography>
        ) : (
          incomingPending.map(({ person, venueName }) => (
            <Box
              key={person.id}
              sx={{ p: 2, mb: 1.5, borderRadius: 3, bgcolor: 'rgba(255,255,255,0.04)' }}
              data-testid={`incoming-${person.id}`}
            >
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                <Typography variant="subtitle2">{person.name}</Typography>
                <Chip size="small" variant="outlined" label={demoHandle(person)} />
                <PersonStatusChip status={person.networkingStatus} />
                <Chip size="small" variant="outlined" label={venueName} />
              </Box>
              <Typography variant="body2" color="text.secondary">
                {person.vibe} · with {person.navitarName} (Lv {person.navitarLevel})
              </Typography>
              <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                <Button
                  size="small"
                  variant="contained"
                  data-testid={`incoming-accept-${person.id}`}
                  onClick={() => acceptIncoming(person.id)}
                >
                  Accept
                </Button>
                <Button
                  size="small"
                  data-testid={`incoming-decline-${person.id}`}
                  onClick={() => declineIncoming(person.id)}
                >
                  Decline
                </Button>
              </Box>
            </Box>
          ))
        )}
      </Paper>

      {/* ---- Add by username (Round 26) ---------------------------- */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="add-by-username-panel">
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center', mb: 1 }}>
          <Typography variant="h5">➕ Add by username</Typography>
          <Chip size="small" label="DEMO" variant="outlined" />
        </Box>
        <Typography variant="body2" color="text.secondary" paragraph>
          Don’t want to wait to run into someone? Type their username and send the request from here
          — it lands in the same place, and they accept or decline just like a request from the list
          below. In the demo, handles are the demo people’s first names — try @maya, @darius or
          @priya.
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
          <TextField
            label="Username — e.g. @maya"
            value={usernameInput}
            onChange={e => {
              setUsernameInput(e.target.value);
              setUsernameResult(null);
            }}
            size="small"
            data-testid="username-input"
            onKeyDown={e => {
              if (e.key === 'Enter' && usernameInput.trim()) submitUsername();
            }}
            sx={{ flex: '1 1 220px' }}
          />
          <Button
            variant="contained"
            data-testid="username-send"
            disabled={!usernameInput.trim()}
            onClick={submitUsername}
          >
            Send request
          </Button>
        </Box>
        {usernameResult && (
          <Typography variant="body2" sx={{ mt: 1.5 }} data-testid="username-result">
            {usernameResult}
          </Typography>
        )}
      </Paper>

      {/* ---- Navitar suggestions ---------------------------------- */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="suggestions-panel">
        <Typography variant="h5" gutterBottom>
          ✨ Your navitar suggests
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Your navitar works the room and brings you people worth meeting — always with the reason
          named. Nothing happens without your approval first, and the other side has to say yes too.
          Never auto-connect, never a forced chat or battle.
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2, alignItems: 'center' }}>
          <Typography variant="body2">Suggestions:</Typography>
          {(['on', 'venues', 'off'] as const).map(freq => (
            <Chip
              key={freq}
              label={freq === 'on' ? 'On' : freq === 'venues' ? 'Only in venues' : 'Off'}
              clickable
              color={social.suggestionFreq === freq ? 'primary' : 'default'}
              onClick={() => update({ ...social, suggestionFreq: freq })}
            />
          ))}
          <Chip
            label={
              networkingStatus === 'quiet'
                ? 'Paused — you’re Just here'
                : visibility === 'invisible'
                  ? 'Paused — you’re Invisible'
                  : 'Presence: suggestions allowed'
            }
            size="small"
            variant="outlined"
          />
        </Box>
        {suggestionsOff ? (
          <Typography variant="body2" color="text.secondary">
            Suggestions are off
            {social.suggestionFreq !== 'off'
              ? ' while your presence is Just here or Invisible — your navitar stays out, by design'
              : ''}
            .
          </Typography>
        ) : social.suggestionFreq === 'venues' && !checkedInVenueId ? (
          <Typography variant="body2" color="text.secondary">
            “Only in venues” is on and you’re not checked in anywhere — check in on the World Map
            and your navitar will work that room.
          </Typography>
        ) : suggestionCandidates.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            No new suggestions right now — everyone nearby is already a friend, passed, or not open
            to meeting.
          </Typography>
        ) : (
          suggestionCandidates.map(({ entry, reason }) => (
            <Box
              key={entry.person.id}
              sx={{ p: 2, mb: 1.5, borderRadius: 3, bgcolor: 'rgba(255,255,255,0.04)' }}
              data-testid={`suggestion-${entry.person.id}`}
            >
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                <Typography variant="subtitle2">{entry.person.name}</Typography>
                <Chip size="small" color="secondary" label={CONTEXT_LABEL[reason.kind]} />
                <Chip size="small" variant="outlined" label={reason.label} />
              </Box>
              <Typography variant="body2" sx={{ mt: 0.5 }}>
                “{reason.detail} Want me to introduce you?”
              </Typography>
              {social.suggestions[entry.person.id] === 'waiting' ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                  Your navitar is doing the warm-up with theirs… waiting on their human’s yes.
                </Typography>
              ) : (
                <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                  <Button
                    size="small"
                    variant="contained"
                    onClick={() => approveSuggestion(entry.person.id, reason.detail)}
                  >
                    Approve — introduce us
                  </Button>
                  <Button size="small" onClick={() => passSuggestion(entry.person.id)}>
                    Pass
                  </Button>
                </Box>
              )}
            </Box>
          ))
        )}
        {social.introductions.length > 0 && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle1" gutterBottom>
              Introductions made
            </Typography>
            {social.introductions.map((intro, i) => {
              const entry = people.find(e => e.person.id === intro.personId);
              return (
                <Typography key={i} variant="body2" sx={{ mb: 1 }}>
                  🤝 <strong>{entry?.person.name ?? 'Someone'}</strong> — {intro.text}
                </Typography>
              );
            })}
          </Box>
        )}
        {Object.entries(social.suggestions)
          .filter(([, s]) => s === 'declined')
          .map(([personId]) => {
            const entry = people.find(e => e.person.id === personId);
            return (
              <Typography key={personId} variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                {entry?.person.name ?? 'They'} passed this time — your navitar handled it
                gracefully. No hard feelings, and it won’t be pushed again.
              </Typography>
            );
          })}
      </Paper>

      {/* ---- People & friend requests ------------------------------ */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h5" gutterBottom>
          People you’ve met &amp; could meet
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Send a friend request — they accept or decline, and nobody is added without a yes. Friends
          can be battled right from here (⚔️ Battle — you’ll see the matchup first), can be invited
          to groups, and can see your home kickback if you choose them.
        </Typography>
        {people.map(({ person, venueName }) => {
          const isFriendNow = friendIds.includes(person.id);
          const req = social.requests[person.id];
          const blocked = social.blocked.includes(person.id);
          return (
            <Box
              key={person.id}
              sx={{
                p: 2,
                mb: 1.5,
                borderRadius: 3,
                bgcolor: 'rgba(255,255,255,0.04)',
                opacity: blocked ? 0.55 : 1,
              }}
              data-testid={`person-${person.id}`}
            >
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                <Typography variant="subtitle2">{person.name}</Typography>
                <PersonStatusChip status={person.networkingStatus} />
                <Chip size="small" variant="outlined" label={venueName} />
                <Chip size="small" variant="outlined" label={demoHandle(person)} />
                {isFriendNow && <Chip size="small" color="success" label="Friend" />}
                {blocked && <Chip size="small" color="error" label="Blocked" />}
              </Box>
              <Typography variant="body2" color="text.secondary">
                {person.vibe} · with {person.navitarName} (Lv {person.navitarLevel})
              </Typography>
              {blocked ? (
                <Button size="small" sx={{ mt: 0.5 }} onClick={() => toggleBlock(person.id)}>
                  Unblock
                </Button>
              ) : isFriendNow ? (
                <Box sx={{ display: 'flex', gap: 1, mt: 0.5 }}>
                  <Button
                    size="small"
                    variant="contained"
                    data-testid={`battle-${person.id}`}
                    onClick={() => battleFriend(person)}
                  >
                    ⚔️ Battle
                  </Button>
                  <Button size="small" color="error" onClick={() => toggleBlock(person.id)}>
                    Block
                  </Button>
                </Box>
              ) : social.incoming[person.id] === 'pending' ? (
                <Typography variant="body2" sx={{ mt: 0.5 }}>
                  🤝 {person.name} sent you a request — answer it in Incoming requests above.
                </Typography>
              ) : req === 'pending' ? (
                <Typography variant="body2" sx={{ mt: 0.5 }}>
                  Request sent — waiting on {person.name}…
                </Typography>
              ) : req === 'declined' ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                  {person.name} passed — your navitar kept it graceful. The door stays closed,
                  politely.
                </Typography>
              ) : (
                <Box sx={{ display: 'flex', gap: 1, mt: 0.5 }}>
                  <Button
                    size="small"
                    variant="outlined"
                    onClick={() => sendRequest(person.id)}
                    data-testid={`request-${person.id}`}
                  >
                    Send friend request
                  </Button>
                  <Button size="small" color="error" onClick={() => toggleBlock(person.id)}>
                    Block
                  </Button>
                </Box>
              )}
            </Box>
          );
        })}
      </Paper>

      {/* ---- Groups ------------------------------------------------- */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="groups-panel">
        <Typography variant="h5" gutterBottom>
          Your groups
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Groups are yours to make and run — GLACER never creates one for you or adds anyone without
          their yes.
        </Typography>
        <TextField
          label="Group name — e.g. Valley battle crew"
          value={groupName}
          onChange={e => setGroupName(e.target.value)}
          fullWidth
          size="small"
          sx={{ mb: 2 }}
        />
        {pickChips(groupPicks, setGroupPicks, 'group-pick')}
        <Button
          variant="contained"
          disabled={!groupName.trim() || groupPicks.length === 0}
          onClick={() => {
            createGroup('group', groupPicks, groupName.trim());
            setGroupName('');
            setGroupPicks([]);
          }}
        >
          Create group &amp; invite
        </Button>

        <Typography variant="subtitle1" sx={{ mt: 3 }} gutterBottom>
          …or start a group chat directly
        </Typography>
        {pickChips(chatPicks, setChatPicks, 'chat-pick')}
        <Button
          variant="outlined"
          disabled={chatPicks.length === 0}
          onClick={() => {
            const names = chatPicks
              .map(id => people.find(e => e.person.id === id)?.person.name ?? '')
              .filter(Boolean)
              .join(', ');
            createGroup('chat', chatPicks, `Chat — ${names}`);
            setChatPicks([]);
          }}
        >
          Start group chat
        </Button>
        {groupNote && (
          <Typography variant="body2" sx={{ mt: 2 }}>
            {groupNote}
          </Typography>
        )}
        {!wingmanActive && (
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            Your presence is Just here / Invisible, so your navitar stays out of group chats — the
            humans can still talk.
          </Typography>
        )}

        {social.groups.length > 0 && (
          <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 1.5 }}>
            {social.groups.map(g => {
              // Round 35: a card's member line counts who is IN
              // the space — removed participants have left it.
              const gMod = modMap[groupSpaceId(g.id)] ?? EMPTY_MODERATION;
              const gActiveMemberIds = activeKeys(gMod, g.memberIds);
              const gAuthorKey = (author?: string): string | null => {
                if (!author) return null;
                const p = people.find(e => e.person.name === author)?.person;
                return p ? `person:${p.id}` : null;
              };
              const gFlow = mergeFlow(g.messages, gMod.systemLines);
              const gParticipants = activeKeys(gMod, [
                'you',
                ...g.memberIds.map(id => `person:${id}`),
              ]).map(k => ({
                key: k,
                label:
                  k === 'you'
                    ? 'You'
                    : (people.find(e => e.person.id === k.slice('person:'.length))?.person.name ??
                      k),
              }));
              const gPinnedItems = gMod.pinnedMessages.flatMap(key => {
                if (gMod.removedMessages.includes(key)) return [];
                const idx = Number(key.split(':')[0]);
                const msg = g.messages[idx];
                if (!msg) return [];
                if (msg.from === 'them') {
                  const k = gAuthorKey(msg.author);
                  if (k && !postRenders(gMod, k, msg.ts)) return [];
                }
                return [
                  {
                    key,
                    authorLabel:
                      msg.from === 'you'
                        ? 'You'
                        : msg.from === 'navitar'
                          ? 'Your navitar'
                          : (msg.author ?? 'Member'),
                    text: msg.text,
                  },
                ];
              });
              return (
                <Box
                  key={g.id}
                  sx={{ p: 2, borderRadius: 3, bgcolor: 'rgba(255,255,255,0.04)' }}
                  data-testid={`group-${g.id}`}
                >
                  <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                    <Typography variant="subtitle2">{g.name}</Typography>
                    <Chip
                      size="small"
                      label={g.kind === 'group' ? 'Group' : 'Group chat'}
                      variant="outlined"
                    />
                    <Chip
                      size="small"
                      label={`${gActiveMemberIds.length} member${gActiveMemberIds.length === 1 ? '' : 's'} accepted`}
                    />
                    {gMod.locked && <Chip size="small" color="error" label="🔒 Locked" />}
                    {g.left && <Chip size="small" color="warning" label="You left" />}
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    Members:{' '}
                    {gActiveMemberIds
                      .map(id => people.find(e => e.person.id === id)?.person.name ?? id)
                      .join(', ') || 'none yet'}
                    {g.declinedIds.length > 0 &&
                      ` · Passed: ${g.declinedIds
                        .map(id => people.find(e => e.person.id === id)?.person.name ?? id)
                        .join(', ')}`}
                  </Typography>
                  <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                    <Button
                      size="small"
                      variant={activeGroupId === g.id ? 'contained' : 'outlined'}
                      onClick={() => setActiveGroupId(activeGroupId === g.id ? null : g.id)}
                    >
                      {activeGroupId === g.id ? 'Close chat' : 'Open chat'}
                    </Button>
                    {!g.left && (
                      <Button size="small" color="warning" onClick={() => leaveGroup(g.id)}>
                        Leave
                      </Button>
                    )}
                  </Box>
                  {activeGroupId === g.id && (
                    <Box sx={{ mt: 2 }}>
                      {g.left ? (
                        <Typography variant="body2" color="text.secondary">
                          You left this {g.kind} — the chat is closed to you. The others carry on
                          without you; leaving is always allowed, no questions.
                        </Typography>
                      ) : (
                        <>
                          {/* Moderation (Round 35): the group is a
                            space the player owns — participants,
                            badges, pins and the lock live here in
                            the chat itself. */}
                          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
                            <Button
                              size="small"
                              variant="outlined"
                              data-testid="mod-lock-toggle"
                              onClick={() =>
                                updateGroupMod(
                                  setLocked(gMod, !gMod.locked, 'group chat', 'owner', Date.now())
                                )
                              }
                            >
                              {gMod.locked ? '🔓 Unlock group chat' : '🔒 Lock group chat'}
                            </Button>
                          </Box>
                          <ParticipantsPanel
                            mod={gMod}
                            ownerKey="you"
                            viewerKey="you"
                            participants={gParticipants}
                            onAppoint={(key, label) =>
                              updateGroupMod(
                                appointModerator(gMod, key, label, 'owner', Date.now())
                              )
                            }
                            onUnappoint={(key, label) =>
                              updateGroupMod(
                                unappointModerator(gMod, key, label, 'owner', Date.now())
                              )
                            }
                            onMute={(key, label) =>
                              updateGroupMod(muteParticipant(gMod, key, label, 'owner', Date.now()))
                            }
                            onUnmute={(key, label) =>
                              updateGroupMod(
                                unmuteParticipant(gMod, key, label, 'owner', Date.now())
                              )
                            }
                            onRemove={(key, label) =>
                              updateGroupMod(
                                removeParticipant(gMod, key, label, 'owner', Date.now())
                              )
                            }
                          />
                          <PinnedArea
                            items={gPinnedItems}
                            canMod
                            onUnpin={key =>
                              updateGroupMod(unpinMessage(gMod, key, 'owner', Date.now()))
                            }
                          />
                          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 2 }}>
                            {g.messages.length === 0 && gMod.systemLines.length === 0 && (
                              <Typography variant="body2" color="text.secondary">
                                No messages yet — say the first word.
                              </Typography>
                            )}
                            {gFlow.map(item => {
                              if (item.kind === 'sys') {
                                return <SystemLineRow key={item.line.id} line={item.line} />;
                              }
                              const m = item.msg;
                              const i = item.index;
                              const mkey = `${i}:${m.ts}`;
                              const aKey = m.from === 'them' ? gAuthorKey(m.author) : null;
                              // A removed member's later posts never render.
                              if (aKey && !postRenders(gMod, aKey, m.ts)) return null;
                              const removedMsg = gMod.removedMessages.includes(mkey);
                              return (
                                <Box
                                  key={i}
                                  sx={{
                                    alignSelf: m.from === 'you' ? 'flex-end' : 'flex-start',
                                    maxWidth: '85%',
                                    p: 1.25,
                                    borderRadius: 3,
                                    bgcolor:
                                      m.from === 'you'
                                        ? 'rgba(18,165,199,0.25)'
                                        : m.from === 'navitar'
                                          ? 'rgba(232,145,45,0.18)'
                                          : 'rgba(255,255,255,0.07)',
                                  }}
                                >
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    {/* Profile picture (Round 34): beside the
                                      player's own group messages only, and
                                      only when a picture is set. */}
                                    {m.from === 'you' && (
                                      <PlayerAvatar size={16} testId="friends-own-avatar" />
                                    )}
                                    <Typography variant="caption" color="text.secondary">
                                      {m.from === 'you'
                                        ? 'You'
                                        : m.from === 'navitar'
                                          ? 'Your navitar (wingman)'
                                          : (m.author ?? 'Member')}
                                    </Typography>
                                    {aKey && <ModBadge role={roleInSpace(gMod, 'you', aKey)} />}
                                    <Box sx={{ marginLeft: 'auto' }}>
                                      <MessageModMenu
                                        messageKey={mkey}
                                        pinned={gMod.pinnedMessages.includes(mkey)}
                                        onPin={() =>
                                          updateGroupMod(
                                            pinMessage(gMod, mkey, 'owner', Date.now())
                                          )
                                        }
                                        onUnpin={() =>
                                          updateGroupMod(
                                            unpinMessage(gMod, mkey, 'owner', Date.now())
                                          )
                                        }
                                        onRemove={() =>
                                          updateGroupMod(
                                            removeMessage(gMod, mkey, 'owner', Date.now())
                                          )
                                        }
                                      />
                                    </Box>
                                  </Box>
                                  {removedMsg ? (
                                    <Typography
                                      variant="body2"
                                      sx={{ fontStyle: 'italic', opacity: 0.75 }}
                                      data-testid="mod-removed-placeholder"
                                    >
                                      {REMOVED_PLACEHOLDER}
                                    </Typography>
                                  ) : (
                                    <Typography variant="body2">{m.text}</Typography>
                                  )}
                                </Box>
                              );
                            })}
                          </Box>
                          {gMod.locked ? (
                            <LockedBanner
                              noun="group chat"
                              canMod
                              onUnlock={() =>
                                updateGroupMod(
                                  setLocked(gMod, false, 'group chat', 'owner', Date.now())
                                )
                              }
                            />
                          ) : (
                            <Box sx={{ display: 'flex', gap: 1 }}>
                              <TextField
                                value={draft}
                                onChange={e => setDraft(e.target.value)}
                                placeholder="Message the group…"
                                size="small"
                                fullWidth
                                onKeyDown={e => {
                                  if (e.key === 'Enter') sendGroupMessage();
                                }}
                              />
                              <Button
                                variant="contained"
                                onClick={sendGroupMessage}
                                disabled={!draft.trim()}
                              >
                                Send
                              </Button>
                            </Box>
                          )}
                        </>
                      )}
                    </Box>
                  )}
                </Box>
              );
            })}
          </Box>
        )}
      </Paper>

      <Paper sx={{ p: 3, textAlign: 'center', bgcolor: 'rgba(33,150,243,0.08)' }}>
        <Typography variant="h6" gutterBottom>
          Got friends in the house? Run a kickback.
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Name your home (a name only — never an address), choose which friends can see it, and host
          a mini venue session at yours.
        </Typography>
        <Button component={RouterLink} to="/kickback" variant="contained" size="large">
          Home Kickbacks →
        </Button>
      </Paper>
    </Container>
  );
};

export default Friends;
