import React, { useEffect, useState } from 'react';
import { Box, IconButton, Typography } from '@mui/material';
import VolumeUpIcon from '@mui/icons-material/VolumeUp';
import VolumeOffIcon from '@mui/icons-material/VolumeOff';
import MusicNoteIcon from '@mui/icons-material/MusicNote';
import MusicOffIcon from '@mui/icons-material/MusicOff';
import {
  isMusicMuted,
  isSoundsMuted,
  setMusicMuted,
  setSoundsMuted,
  subscribeSound,
  unlockAudio,
  type SoundChannels,
} from '../utils/sound';

// The channel sound toggles (Round 36.15, Eddie 2026-11-24 —
// revises the 2026-11-16 single global mute): TWO independent
// controls in the Navbar — MUSIC (the signature loop) and
// SOUNDS (navitar cries, battle effect sounds, stage
// ambience). Each silences only its own channel, each persists
// on its own localStorage key, and each carries its label at
// every width (the old single caption hid on phones, exactly
// where Eddie went looking for a music mute). Sound is ON by
// default on both channels, but per browser law nothing plays
// until the first tap anywhere; a toggle's own tap also
// unlocks. The sounds toggle keeps the original
// nav-sound-toggle testid; the music toggle is
// nav-music-toggle.
//
// FIT (Round 36.15): the phone toolbar's content fit its 388px
// client width EXACTLY before this round (measured), so the
// second toggle had zero headroom — the cells are trimmed to
// the icon's own width with the label under it, and Navbar
// carries matching xs-only padding trims (the Round 17/22 fit
// pattern; desktop untouched). Measured after: toolbar
// scrollWidth ≤ clientWidth, no page overflow at 390px.
const SoundToggle: React.FC = () => {
  const [channels, setChannels] = useState<SoundChannels>(() => ({
    music: isMusicMuted(),
    sounds: isSoundsMuted(),
  }));

  useEffect(() => subscribeSound(setChannels), []);

  const toggleMusic = () => {
    unlockAudio();
    setMusicMuted(!channels.music);
  };

  const toggleSounds = () => {
    unlockAudio();
    setSoundsMuted(!channels.sounds);
  };

  const cellSx = {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    width: 25,
  } as const;

  const labelSx = {
    fontSize: '0.5rem',
    lineHeight: 1,
    mt: -0.25,
    color: 'text.secondary',
    letterSpacing: '0.02em',
  } as const;

  return (
    <Box sx={{ display: 'flex', alignItems: 'flex-start', mr: { xs: 0, sm: 0.5 } }}>
      <Box sx={cellSx}>
        <IconButton
          color="inherit"
          onClick={toggleMusic}
          aria-label={channels.music ? 'Unmute music' : 'Mute music'}
          aria-pressed={channels.music}
          data-testid="nav-music-toggle"
          size="small"
          sx={{ p: 0.25 }}
        >
          {channels.music ? <MusicOffIcon fontSize="small" /> : <MusicNoteIcon fontSize="small" />}
        </IconButton>
        <Typography variant="caption" sx={labelSx}>
          Music
        </Typography>
      </Box>
      <Box sx={cellSx}>
        <IconButton
          color="inherit"
          onClick={toggleSounds}
          aria-label={channels.sounds ? 'Unmute sounds' : 'Mute sounds'}
          aria-pressed={channels.sounds}
          data-testid="nav-sound-toggle"
          size="small"
          sx={{ p: 0.25 }}
        >
          {channels.sounds ? <VolumeOffIcon fontSize="small" /> : <VolumeUpIcon fontSize="small" />}
        </IconButton>
        <Typography variant="caption" sx={labelSx}>
          Sounds
        </Typography>
      </Box>
    </Box>
  );
};

export default SoundToggle;
