// Quick-swap sheet (Eddie, 2026-11-16 ~09:29 PT): "whether it's
// on a stroll, before battle, or whatever — we need a swap
// button." Every surface that USES the active navitar gets a
// clear Swap button; picking in this sheet changes the active
// navitar through the ONE existing path — FightClub's
// setActiveNavitar(id), which updates activeNavitarId state and
// (via the provider's persistence effect) writes localStorage
// `glacer-active-navitar-id`. userNavitar is derived from that
// id, so Stroll's companion, Battle Step 1, Profile and the map
// companion all update immediately, in place, no reload. There
// is NO Stroll-only / map-only selection state here, and picking
// never starts a battle or changes presence.
//
// The list is the player's selectable navitars — the same
// FightClub `navitars` collection Battle Step 1 offers (locked
// designs are not in that collection, so they never appear).
import React, { useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
} from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { elementEmoji } from '../utils/navitarArt';
import { resolveShowcaseModel } from '../utils/modelResolution';
import { saveSwapReturn } from '../utils/swapReturn';

export const SwapNavitarButton: React.FC<{
  label: string;
  size?: 'small' | 'medium' | 'large';
  variant?: 'contained' | 'outlined' | 'text';
  sx?: Record<string, unknown>;
}> = ({ label, size = 'medium', variant = 'outlined', sx }) => {
  const { navitars, userNavitar, activeNavitarId, setActiveNavitar, businessNavitars } =
    useNavitarFightClub();
  const [open, setOpen] = useState(false);
  const activeId = activeNavitarId ?? userNavitar?.id ?? null;

  const pick = (id: string) => {
    // THE write path — the same one Navidex Choose and Battle
    // Step 1 use. Nothing else is written anywhere.
    setActiveNavitar(id);
    setOpen(false);
  };

  return (
    <>
      <Button size={size} variant={variant} onClick={() => setOpen(true)} sx={sx}>
        {label}
      </Button>
      <Dialog open={open} onClose={() => setOpen(false)} fullWidth maxWidth="xs">
        <DialogTitle>🔄 Swap — choose your navitar</DialogTitle>
        <DialogContent>
          {navitars.length === 0 ? (
            <Typography variant="body2" color="text.secondary">
              {/* Round 16: adoption/creation live on the Home page
                  (the Navidex choose is owned-only now), so the
                  directions point at the real on-ramp. */}
              You have no navitars yet — adopt or create one on the Home page first, then swap to it
              here.
            </Typography>
          ) : (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              {navitars.map(n => {
                const selected = n.id === activeId;
                // Round 8: the 3D tag — this fighter stands in the
                // arena (and AR stroll) as a real model, via the
                // shared showcase chain. Battle Step 1 points here
                // when the current fighter has no model.
                const hasModel = !!resolveShowcaseModel(n, businessNavitars);
                return (
                  <Button
                    key={n.id}
                    variant={selected ? 'contained' : 'outlined'}
                    onClick={() => pick(n.id)}
                    sx={{
                      textTransform: 'none',
                      justifyContent: 'flex-start',
                      ...(selected ? { boxShadow: '0 0 0 3px #ffd54f', fontWeight: 'bold' } : {}),
                    }}
                  >
                    {elementEmoji(n.element)} {n.name} · Lv. {n.level} · {n.element} · HP {n.hp}/
                    {n.maxHp}
                    {hasModel ? ' · 3D' : ''}
                    {selected ? ' — ✓ current' : ''}
                  </Button>
                );
              })}
            </Box>
          )}
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
            This is the same choice as the Navidex Choose button — one active navitar everywhere:
            Stroll companion, battles, Profile and the map.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button component={RouterLink} to="/collection" onClick={() => setOpen(false)}>
            Open Navidex
          </Button>
          <Button onClick={() => setOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

// Pre-fight swap (Round 14, Eddie 2026-11-17: "when I swap my
// fighter I need to go straight to my Navidex"): on the two
// PRE-FIGHT surfaces — the /challenge screen and Battle Step 1 —
// the swap button does NOT open the sheet above. It stamps the
// swap-return context (utils/swapReturn.ts) and navigates to the
// Navidex, where the banner names the errand and, once a ✓ pick
// lands, offers the way back to the pairing. The pick itself still
// writes through the ONE choose path (useChooseNavitar →
// glacer-active-navitar-id) — this button only carries the
// context, never a selection. Stroll / Profile / Map keep the
// in-place sheet (SwapNavitarButton above): a companion swap
// mid-stroll is a different errand from a pre-fight one.
export const NavidexSwapButton: React.FC<{
  label: string;
  size?: 'small' | 'medium' | 'large';
  variant?: 'contained' | 'outlined' | 'text';
  sx?: Record<string, unknown>;
  returnTo: string;
  contextLabel: string;
}> = ({ label, size = 'medium', variant = 'outlined', sx, returnTo, contextLabel }) => {
  const navigate = useNavigate();
  return (
    <Button
      size={size}
      variant={variant}
      sx={sx}
      data-testid="navidex-swap-button"
      onClick={() => {
        saveSwapReturn({ returnTo, contextLabel });
        navigate('/collection');
      }}
    >
      {label}
    </Button>
  );
};

export default SwapNavitarButton;
