import type { NavitarDesignProps } from '../components/NavitarDesign';
import { sampleNavitars } from '../data/sampleNavitars';
import {
  COLLECTION_DESIGNS,
  PRIME_DESIGNS,
  PRIME_ZERO_DESIGN,
  REALM_CANDIDATE_DESIGNS,
  type CollectionDesign,
} from './collectionDesigns';
import { NAVITAR_LORE } from './navitarArt';
import { designCardStats } from './designStats';

// Card data by fighter name (Round 30): the ONE resolver every
// surface uses when it needs a fighter's full player card away
// from the Navidex grids — above all the summon/load veil, where
// Eddie's law is that the loading screen IS the card. The props
// assembled here are the same ones the Navidex itself renders:
// the showcase heroes carry their roster record (stats, lore,
// level, rarity); the two bar-loop fighters carry the Showcase's
// own display entries (mirrored verbatim from NavitarShowcase);
// every other design carries its collection record — tier,
// signature ability, and the composed lore (ability line +
// flavor) exactly as the owner cards compose it. A name with no
// record anywhere resolves to null and the caller keeps its
// previous treatment — data is never invented for a card.

const ALL_DESIGNS: CollectionDesign[] = [
  ...COLLECTION_DESIGNS,
  ...PRIME_DESIGNS,
  ...REALM_CANDIDATE_DESIGNS,
  PRIME_ZERO_DESIGN,
];

function fromDesign(design: CollectionDesign): NavitarDesignProps {
  const lore =
    [
      design.abilityName && design.abilityText
        ? `${design.abilityName} — ${design.abilityText}`
        : null,
      design.flavor,
    ]
      .filter(Boolean)
      .join(' ') || undefined;
  return {
    name: design.name,
    type: design.element as NavitarDesignProps['type'],
    imageUrl: design.portrait ? `${process.env.PUBLIC_URL}/navitars/${design.portrait}` : undefined,
    lore,
    // Round 36.11: the design's own stat block (utils/designStats.ts)
    // — the Stage card's picture overlay now prints its HP and the
    // card body its stat bars, like every roster fighter's card.
    stats: designCardStats(design.name),
    tier: design.tier ?? undefined,
    abilityName: design.abilityName ?? undefined,
    placeholderArt: !design.portrait,
    navidexNum: design.num,
    epithet: design.epithet ?? undefined,
  };
}

// The bar-loop pair, mirrored from their NavitarShowcase entries
// (the numbers are the Showcase's documented display defaults).
const ASHWING_CARD: NavitarDesignProps = {
  name: 'Ashwing',
  type: 'fire',
  level: 2,
  imageUrl: `${process.env.PUBLIC_URL}/navitars/ashwing.webp`,
  stats: { health: 80, attack: 80, defense: 65, speed: 85 },
  lore: NAVITAR_LORE.ashwing,
};

const GRIFFIN_CARD: NavitarDesignProps = {
  name: 'Griffin',
  type: 'ice',
  level: 2,
  rarity: 'rare',
  stats: { health: 80, attack: 75, defense: 70, speed: 80 },
  lore: NAVITAR_LORE.griffin,
};

export function cardDataFor(name: string): NavitarDesignProps | null {
  const hero = sampleNavitars.find(n => n.name === name);
  if (hero) {
    const design = ALL_DESIGNS.find(d => d.name === name);
    return {
      ...hero,
      navidexNum: design?.num,
      epithet: design?.epithet ?? undefined,
    };
  }
  if (name === 'Ashwing') return ASHWING_CARD;
  if (name === 'Griffin') return GRIFFIN_CARD;
  const design = ALL_DESIGNS.find(d => d.name === name);
  return design ? fromDesign(design) : null;
}
